package com.fasterxml.jackson.core.sym;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.util.InternCache;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ByteQuadsCanonicalizer.toString()
 */
public class ByteQuadsCanonicalizer_toString_TriageGen2Test {

    @Test
    public void testToString_Empty() {
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        // Expected format: [className: size=0, hashSize=N, 0/0/0/0 pri/sec/ter/spill (=0), total:0]
        // Note: hashSize and _count depend on internal implementation, 
        // but we check the structure and the counts.
        String result = canonicalizer.toString();

        assertNotNull(result);
        assertTrue(result.startsWith("[com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer:"));
        assertTrue(result.contains("size="));
        assertTrue(result.contains("hashSize="));
        assertTrue(result.contains("0/0/0/0 pri/sec/ter/spill (=0)"));
        assertTrue(result.contains("total:0"));

        canonicalizer.release();
    }

    @Test
    public void testToString_WithData() {
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        // Add some data to trigger different counts (pri/sec/ter/spill)
        // Adding names with different hash characteristics to force collisions/distribution
        canonicalizer.addName("test1", 0x01020304);
        canonicalizer.addName("test2", 0x01020304); // Potential collision depending on hash
        canonicalizer.addName("test3", 0x05060708);

        String result = canonicalizer.toString();

        assertNotNull(result);
        // Verify that the string contains the class name
        assertTrue(result.contains("ByteQuadsCanonicalizer"));

        // Verify the summary math in the string: (pri+sec+tert+spill)
        // We extract the part inside (=X) to ensure logic consistency
        int startIdx = result.indexOf("(=") + 2;
        int endIdx = result.indexOf(")", startIdx);
        String sumStr = result.substring(startIdx, endIdx);
        int calculatedSum = Integer.parseInt(sumStr);

        assertEquals("The sum in toString must match totalCount", 
                     canonicalizer.totalCount(), calculatedSum);

        canonicalizer.release();
    }

    @Test
    public void testToString_ChildInstance() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        ByteQuadsCanonicalizer child = root.makeChild(0);

        String result = child.toString();

        assertNotNull(result);
        assertTrue(result.contains("ByteQuadsCanonicalizer"));

        // Ensure the counts are at least 0 for a fresh child
        assertTrue(result.contains("0/0/0/0"));

        root.release();
        child.release();
    }
}
